#[test]
fn the_helmholtz_energy_matches_the_source() {
    let model = LjsBh::new();
    let mut checked = 0;
    for row in include_str!("fixtures/ljs_helmholtz.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let temperature: f64 = parts[0].parse().unwrap();
        let volume: f64 = parts[1].parse().unwrap();
        let moles: f64 = parts[2].parse().unwrap();
        let lafitte = parts[3].parse::<i32>().unwrap() == 1;
        let source: f64 = fields[1].parse().unwrap();
        let source_t: f64 = fields[2].parse().unwrap();
        let mut model = model;
        if lafitte {
            model.set_control(LjsControl {
                use_lafitte_a3: true,
                ..LjsControl::default()
            });
        }
        let (energy, derivative) = model
            .residual_helmholtz_energy_derivative(temperature, volume, moles)
            .unwrap();
        let native = energy * moles;
        let native_t = derivative * moles;
        assert!(
            (source - native).abs() <= ATOL + RTOL * source.abs(),
            "{case}: source {source} native {native}"
        );
        assert!(
            (source_t - native_t).abs() <= ATOL + RTOL * source_t.abs(),
            "{case}: source {source_t} native {native_t}"
        );
        checked += 1;
    }
    assert_eq!(checked, 12);
}

#[test]
fn the_state_matches_the_source() {
    let model = LjsBh::new();
    let mut checked = 0;
    for row in include_str!("fixtures/ljs_state.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let parts: Vec<_> = case.split('|').collect();
        let temperature: f64 = parts[0].parse().unwrap();
        let pressure: f64 = parts[1].parse().unwrap();
        let source_volume: f64 = fields[1].parse().unwrap();
        let source_compressibility: f64 = fields[2].parse().unwrap();
        let (native_pressure, native_compressibility) =
            model.pressure(temperature, source_volume, 1.0).unwrap();
        assert!(
            (native_pressure - pressure).abs() <= 1.0e-6 * pressure.abs(),
            "{case}: source {pressure} native {native_pressure}"
        );
        assert!(
            (source_compressibility - native_compressibility).abs()
                <= 1.0e-9 + 1.0e-6 * source_compressibility.abs(),
            "{case}: source {source_compressibility} native {native_compressibility}"
        );
        checked += 1;
    }
    assert_eq!(checked, 8);
}

#[test]
fn the_volume_solve_returns_a_state_of_the_pressure() {
    let model = LjsBh::new();
    for (temperature, pressure) in [(100.0, 1.0e5), (150.0, 1.0e6), (200.0, 5.0e6)] {
        let volume = model
            .volume(temperature, pressure, thermopack_rs::Phase::Vapor)
            .unwrap();
        let (value, _) = model.pressure(temperature, volume, 1.0).unwrap();
        assert!(
            (value - pressure).abs() <= 1.0e-6 * pressure.abs(),
            "{temperature} K: {value} against {pressure}"
        );
    }
}

#[test]
fn the_reduced_potential_matches_the_source() {
    let model = LjsBh::new();
    let mut checked = 0;
    for row in include_str!("fixtures/ljs_potential.csv").lines().skip(1) {
        let fields: Vec<_> = row.split(';').collect();
        let case = fields[0];
        let separations: Vec<f64> = case.split(',').map(|v| v.parse().unwrap()).collect();
        let source: Vec<f64> = fields[1].split(',').map(|v| v.parse().unwrap()).collect();
        let (potential, force) = model.reduced_potential(&separations);
        for index in 0..separations.len() {
            let source_potential = source[2 * index];
            let source_force = source[2 * index + 1];
            assert!(
                (source_potential - potential[index]).abs()
                    <= 1.0e-14 + 1.0e-12 * source_potential.abs(),
                "{case} potential {index}: source {source_potential} native {}",
                potential[index]
            );
            assert!(
                (source_force - force[index]).abs() <= 1.0e-14 + 1.0e-12 * source_force.abs(),
                "{case} force {index}: source {source_force} native {}",
                force[index]
            );
        }
        // The force is the negative derivative of the potential.
        let step = 1.0e-6 * separations[0];
        let (upper, _) = model.reduced_potential(&[separations[0] + step]);
        let (lower, _) = model.reduced_potential(&[separations[0] - step]);
        let slope = -(upper[0] - lower[0]) / (2.0 * step);
        assert!(
            (slope - force[0]).abs() < 1.0e-4 * slope.abs().max(1.0),
            "{case} force: {slope} against {}",
            force[0]
        );
        checked += 1;
    }
    assert_eq!(checked, 4);
}

